.radio-body { display: flex; flex-direction: column; flex: 1; line-height: 1.4; }
.radio-price { font-weight: 700; white-space: nowrap; }
.pay-mark { display: inline-flex; align-items: center; height: 28px; padding: 0 10px; border-radius: var(--r-sm); border: 1px solid var(--border); background: #fff; font-size: 12px; font-weight: 800; white-space: nowrap; }
.bank-slot:not(:empty) { margin-top: 16px; }
.bank-field { max-width: 360px; }
.info-box { display: flex; gap: 14px; padding: 18px; border-radius: var(--r-md); background: var(--panel); line-height: 1.55; }
.co-final { display: flex; flex-direction: column; gap: 16px; padding-top: 8px; }
.form-alert { display: flex; align-items: center; gap: 8px; padding: 12px 16px; border-radius: var(--r-md); border: 1.5px solid var(--error); color: var(--error); font-weight: 600; font-size: 14px; background: #fff; }
.place-btn { height: 56px; font-size: 17px; }
.co-note { text-align: center; }
.summary-checkout { top: 96px; }
.co-lines { display: grid; gap: 14px; padding-bottom: 16px; border-bottom: 1px solid rgba(11, 37, 69, .15); }
.co-lines li { display: grid; grid-template-columns: 64px minmax(0, 1fr) auto; align-items: center; gap: 14px; }
.co-thumb { position: relative; display: block; background: #fff; border-radius: var(--r-md); }
.co-thumb .visual { aspect-ratio: 1; }
.co-qty { position: absolute; top: -6px; right: -6px; display: grid; place-items: center; min-width: 22px; height: 22px; padding: 0 6px; border-radius: var(--r-sm); background: var(--navy); color: #fff; font-size: 12px; font-weight: 700; }
.co-line-body { display: flex; flex-direction: column; font-size: 14px; line-height: 1.35; }
.co-line-price { font-weight: 600; font-size: 15px; }
.co-trust { display: grid; gap: 14px; padding-top: 16px; border-top: 1px solid rgba(11, 37, 69, .15); }
.co-trust li { display: flex; gap: 12px; font-size: 13px; color: var(--muted); line-height: 1.4; }
.co-trust .ic { color: var(--navy); margin-top: 1px; }
.co-trust strong { display: block; font-size: 14px; color: var(--navy); }
.mobile-summary { display: none; }
.confirm { display: flex; flex-direction: column; align-items: center; gap: 16px; max-width: 720px; margin: 24px auto; text-align: center; }
.confirm-ic { display: grid; place-items: center; width: 80px; height: 80px; border-radius: 50%; background: var(--panel); color: var(--navy); }
.confirm .lead { margin-inline: auto; }
.confirm-steps { display: grid; gap: 12px; width: 100%; margin: 16px 0; text-align: left; }
.confirm-steps li { display: flex; gap: 16px; align-items: flex-start; padding: 20px; border: 1px solid var(--border); border-radius: var(--r-lg); }
.confirm-steps .step-num { width: 36px; height: 36px; font-size: 15px; margin: 0; }
.confirm-step-title { font-size: 16px; font-weight: 700; margin-bottom: 2px; }

/* ---------- Over ons ---------- */
.hero-grid-about { grid-template-columns: minmax(0, 1.3fr) minmax(0, .9fr); }
.quote-card { display: flex; flex-direction: column; gap: 20px; padding: 40px; border-radius: 12px; background: var(--navy); color: #fff; }
.quote-card .ic { color: var(--sky-light); }
.quote-card blockquote { font-size: 28px; line-height: 1.3; font-weight: 700; font-style: italic; }
.quote-card figcaption { font-size: 14px; color: rgba(255, 255, 255, .78); padding-top: 16px; border-top: 1px solid rgba(255, 255, 255, .18); }
.about-split { display: grid; grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr); gap: 64px; align-items: start; }
.principle-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.principle { display: flex; flex-direction: column; gap: 10px; padding: 28px 24px; background: #fff; border-radius: var(--r-lg); border: 1px solid var(--border); }
.principle .t-h3 { font-size: 19px; margin-top: 8px; }
.principle p { color: var(--muted); font-size: 15px; }
.combo { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr); align-items: stretch; gap: 16px; }
.combo-card { display: flex; flex-direction: column; align-items: flex-start; gap: 10px; padding: 28px; border-radius: var(--r-lg); border: 1px solid var(--border); background: #fff; }
.combo-card .eyebrow { margin: 8px 0 0; }
.combo-card .checklist { margin: 4px 0 8px; }
.combo-card .link { margin-top: auto; }
.combo-ic { display: grid; place-items: center; width: 64px; height: 64px; border-radius: var(--r-lg); background: var(--panel); color: var(--navy); }
.combo-plus, .combo-eq { display: grid; place-items: center; align-self: center; width: 44px; height: 44px; border-radius: 50%; background: var(--yellow); color: var(--navy); font-size: 24px; font-weight: 800; }
.combo-result { background: var(--navy); border-color: var(--navy); color: #fff; }
.combo-result .t-h3 { color: #fff; }
.combo-result .combo-ic { background: rgba(255, 255, 255, .1); color: var(--sky-light); }
.combo-result p { color: rgba(255, 255, 255, .84); }
.expect-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.expect-list li { display: flex; gap: 14px; align-items: flex-start; padding: 22px; background: #fff; border-radius: var(--r-lg); border: 1px solid var(--border); }
.expect-list .ic { width: 26px; height: 26px; color: var(--navy); }
.expect-title { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.notice { display: flex; gap: 20px; align-items: flex-start; padding: 32px; border-radius: var(--r-lg); border: 1.5px solid var(--sky-light); background: #fff; }
.notice-ic { display: grid; place-items: center; width: 56px; height: 56px; border-radius: 50%; background: var(--panel); flex: none; }
.notice p { margin-top: 6px; color: var(--muted); max-width: 820px; }

/* ---------- FAQ page ---------- */
.faq-hero .lead { margin-top: 12px; }
.faq-layout { display: grid; grid-template-columns: 280px minmax(0, 1fr); gap: 48px; align-items: start; }
.faq-side { position: sticky; top: 104px; }
.faq-cats { display: grid; gap: 4px; }
.faq-cat { display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 100%; min-height: 48px; padding: 0 14px; border-radius: var(--r-md); font-weight: 600; font-size: 15px; text-align: left; transition: background-color .15s; }
.faq-cat:hover { background: var(--page); }
.faq-cat.is-active { background: var(--navy); color: #fff; }
.faq-cat.is-active .chip-count { color: var(--sky-light); }
.faq-main { display: flex; flex-direction: column; gap: 40px; min-width: 0; }
.faq-main > .result-count { margin-bottom: -24px; }
.faq-group-title { margin-bottom: 16px; }
.contact-layout { display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); gap: 56px; align-items: start; }
.contact-intro .t-h2 { margin-bottom: 8px; }
.contact-list { display: grid; gap: 16px; margin-top: 28px; }
.contact-list li { display: flex; gap: 14px; align-items: center; }
.contact-list strong { display: block; font-size: 14px; }
.contact-ic { display: grid; place-items: center; width: 48px; height: 48px; border-radius: var(--r-lg); background: #fff; border: 1px solid var(--border); flex: none; }
.contact-card { padding: 32px; background: #fff; border-radius: var(--r-lg); border: 1px solid var(--border); }
.contact-form { display: flex; flex-direction: column; align-items: flex-start; gap: 24px; }
.contact-form .field-grid { width: 100%; }
.sent { display: flex; flex-direction: column; align-items: center; gap: 12px; padding: 32px 0; text-align: center; }

/* ==========================================================================
   Responsive (container queries on .site)
   ========================================================================== */
@container site (max-width: 1500px) {
  .nav-contact, .cart-link-label { display: none; }
  .cart-link { padding: 0 10px 0 12px; }
}

@container site (max-width: 1240px) {
  .header-cta { display: none; }
  .header-bar { gap: 20px; }
  .usp-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }

